            console.warn(`Invalid totalOfChargesTable: ${totalOfChargesTable}, using 0`);
            yield put(PaymentChargesTableAction.fullCreditsTableUpdate([]));
            return { result: ResultType.SUCCESS };
        }

        // Early return if no data to process
        if (creditTableLines.length === 0 || totalOfChargesTable <= 0) {
            yield put(PaymentChargesTableAction.fullCreditsTableUpdate([]));
            return { result: ResultType.SUCCESS };
        }

        // Process with minimal copying and single pass
        let remainingBalance = totalOfChargesTable;
        const updatedCreditTable: CreditChargesPaymentTypes[] = [];
        let hasUpdates = false;

        for (const credit of creditTableLines) {
            // Skip invalid credits
            if (typeof credit.txnId !== 'string' || 
                typeof credit.openBalance !== 'number' || 
                credit.openBalance < 0) {
                updatedCreditTable.push(credit);
                continue;
            }

            // Only process if linkedPaymentAmount exists and is non-empty
            if (!credit.linkedPaymentAmount?.trim()) {
                updatedCreditTable.push(credit);
                continue;
            }

            // Create copy only if we need to modify
            hasUpdates = true;
            const creditCopy = cloneDeep(credit);

            if (remainingBalance > 0) {
                if (remainingBalance >= credit.openBalance) {
                    creditCopy.linkedPaymentAmount = credit.openBalance.toString();
                    remainingBalance -= credit.openBalance;
                } else {
                    creditCopy.linkedPaymentAmount = remainingBalance.toString();
                    remainingBalance = 0;
                }
            } else {
                creditCopy.linkedPaymentAmount = '';
            }

            updatedCreditTable.push(creditCopy);
        }

        // Only dispatch update if there were changes
        if (hasUpdates) {
            yield put(PaymentChargesTableAction.fullCreditsTableUpdate(updatedCreditTable));
        }

        return { result: ResultType.SUCCESS };
    } catch (error) {
        console.error('Error in outstandingTransactionsHandler:', error);
        return { result: ResultType.FAILURE };
    }
}
