# Building a Toy RDBMS: Common Pitfalls and Error Handling in Query Parsing

## Common Pitfalls and Error Handling in SQL Query Parsing

When implementing a query parser that converts SQL AST to relational algebra, several common pitfalls and edge cases can arise. Proper error handling is crucial for building a robust parser that provides clear feedback and prevents unexpected failures.

### Key Challenges in Query Parsing

1. **Ambiguous Column References**: When multiple tables have columns with the same name
2. **Type Mismatches**: Comparing incompatible data types in conditions
3. **Invalid SQL Syntax**: Malformed or unsupported SQL constructs
4. **Circular Dependencies**: JOIN conditions that create infinite loops
5. **NULL Value Handling**: Special semantics for NULL comparisons
6. **Recursion Depth**: Deeply nested queries causing stack overflow

## Enhanced Parser with Comprehensive Error Handling

Here's an enhanced version of our query parser with robust error handling:

```python
from dataclasses import dataclass
from typing import List, Optional, Union, Any, Dict, Set
from enum import Enum

# ============================================
# Custom Exception Classes
# ============================================

class QueryParserError(Exception):
    """Base exception for query parser errors"""
    pass

class SyntaxError(QueryParserError):
    """Raised when SQL syntax is invalid"""
    pass

class SemanticError(QueryParserError):
    """Raised when SQL semantics are invalid"""
    pass

class UnsupportedFeatureError(QueryParserError):
    """Raised when encountering unsupported SQL features"""
    pass

# ============================================
# Enhanced AST Nodes with Validation
# ============================================

class Operator(Enum):
    """Valid comparison operators"""
    EQUAL = "="
    NOT_EQUAL = "!="
    LESS_THAN = "<"
    GREATER_THAN = ">"
    LESS_EQUAL = "<="
    GREATER_EQUAL = ">="
    LIKE = "LIKE"
    IN = "IN"
    IS_NULL = "IS NULL"
    IS_NOT_NULL = "IS NOT NULL"

class JoinType(Enum):
    """Valid join types"""
    INNER = "INNER"
    LEFT = "LEFT"
    RIGHT = "RIGHT"
    FULL = "FULL"

@dataclass
class SQL_AST:
    """Base class for SQL AST nodes"""
    def validate(self):
        """Validate this AST node"""
        pass

@dataclass
class Condition(SQL_AST):
    """Simple condition like column = value"""
    column: str
    operator: str
    value: Any

    def validate(self):
        """Validate condition structure"""
        if not self.column or not isinstance(self.column, str):
            raise SyntaxError(f"Invalid column name: {self.column}")

        if not self.operator or not isinstance(self.operator, str):
            raise SyntaxError(f"Invalid operator: {self.operator}")

        # Check if operator is valid
        try:
            Operator(self.operator.upper())
        except ValueError:
            valid_ops = [op.value for op in Operator]
            raise SyntaxError(
                f"Invalid operator: {self.operator}. "
                f"Valid operators are: {', '.join(valid_ops)}"
            )

        # Special handling for NULL values
        if self.value is None and self.operator.upper() not in ["IS NULL", "IS NOT NULL"]:
            raise SemanticError(
                f"Cannot use operator '{self.operator}' with NULL value. "
                f"Use 'IS NULL' or 'IS NOT NULL' instead."
            )

@dataclass
class SelectStatement(SQL_AST):
    """SELECT statement AST"""
    columns: List[str]
    table: str
    where_clause: Optional[Condition] = None

    def validate(self):
        """Validate SELECT statement"""
        # Check table name
        if not self.table or not isinstance(self.table, str):
            raise SyntaxError(f"Invalid table name: {self.table}")

        # Check columns
        if not self.columns:
            raise SyntaxError("SELECT statement must have at least one column")

        for column in self.columns:
            if not column or not isinstance(column, str):
                raise SyntaxError(f"Invalid column name: {column}")

        # Validate WHERE clause if present
        if self.where_clause:
            self.where_clause.validate()

@dataclass
class JoinClause(SQL_AST):
    """Represents a JOIN clause"""
    left_table: str
    right_table: str
    join_type: str
    condition: Optional[Condition] = None

    def validate(self):
        """Validate JOIN clause"""
        # Check join type
        try:
            JoinType(self.join_type.upper())
        except ValueError:
            valid_joins = [jt.value for jt in JoinType]
            raise SyntaxError(
                f"Invalid join type: {self.join_type}. "
                f"Valid join types are: {', '.join(valid_joins)}"
            )

        # Check table names
        if not self.left_table or not isinstance(self.left_table, str):
            raise SyntaxError(f"Invalid left table name: {self.left_table}")

        if not self.right_table or not isinstance(self.right_table, str):
            raise SyntaxError(f"Invalid right table name: {self.right_table}")

        # Tables cannot join with themselves without aliases
        if self.left_table == self.right_table:
            raise SemanticError(
                f"Cannot join table '{self.left_table}' with itself. "
                f"Use table aliases for self-joins."
            )

        # Validate condition if present
        if self.condition:
            self.condition.validate()

@dataclass
class SelectWithJoin(SQL_AST):
    """SELECT statement with JOIN"""
    columns: List[str]
    joins: List[JoinClause]
    where_clause: Optional[Condition] = None

    def validate(self):
        """Validate SELECT statement with JOINs"""
        # Check columns
        if not self.columns:
            raise SyntaxError("SELECT statement must have at least one column")

        for column in self.columns:
            if not column or not isinstance(column, str):
                raise SyntaxError(f"Invalid column name: {column}")

        # Check JOINs
        if not self.joins:
            raise SyntaxError("SelectWithJoin must have at least one JOIN")

        # Validate all JOIN clauses
        for join_clause in self.joins:
            join_clause.validate()

        # Check for circular JOIN dependencies
        self._detect_join_cycles()

        # Validate WHERE clause if present
        if self.where_clause:
            self.where_clause.validate()

    def _detect_join_cycles(self):
        """Detect circular dependencies in JOIN clauses"""
        # Build adjacency list
        adjacency = {}
        for join in self.joins:
            if join.left_table not in adjacency:
                adjacency[join.left_table] = set()
            adjacency[join.left_table].add(join.right_table)

        # Detect cycles using DFS
        visited = set()
        recursion_stack = set()

        def dfs(node):
            if node in recursion_stack:
                # Found a cycle
                cycle_path = list(recursion_stack)
                cycle_path.append(node)
                raise SemanticError(
                    f"Circular JOIN dependency detected: {' -> '.join(cycle_path)}"
                )

            if node in visited:
                return

            visited.add(node)
            recursion_stack.add(node)

            if node in adjacency:
                for neighbor in adjacency[node]:
                    dfs(neighbor)

            recursion_stack.remove(node)

        # Start DFS from each node
        for node in adjacency:
            if node not in visited:
                dfs(node)

# ============================================
# Enhanced Query Parser with Error Handling
# ============================================

class RobustQueryParser:
    """Query parser with comprehensive error handling and validation"""

    def __init__(self, schema_registry: Optional[Dict[str, Dict[str, str]]] = None):
        """
        Initialize parser with optional schema registry.

        Args:
            schema_registry: Dictionary mapping table names to their schemas
                Example: {"students": {"id": "INTEGER", "name": "STRING", "age": "INTEGER"}}
        """
        self.schema = schema_registry or {}
        self.max_recursion_depth = 100
        self.current_recursion_depth = 0

    def parse(self, sql_ast: SQL_AST) -> RA_Node:
        """
        Parse SQL AST to relational algebra AST with comprehensive error handling.

        Args:
            sql_ast: The SQL Abstract Syntax Tree to parse

        Returns:
            RA_Node: Root of the relational algebra AST

        Raises:
            QueryParserError: For any parsing errors
        """
        try:
            # Reset recursion depth
            self.current_recursion_depth = 0

            # Validate input
            if sql_ast is None:
                raise SyntaxError("SQL AST cannot be None")

            # Validate the SQL AST structure
            sql_ast.validate()

            # Additional semantic validation with schema if available
            if self.schema:
                self._validate_with_schema(sql_ast)

            # Parse based on AST type
            if isinstance(sql_ast, SelectStatement):
                return self._parse_simple_select(sql_ast)
            elif isinstance(sql_ast, SelectWithJoin):
                return self._parse_select_with_join(sql_ast)
            else:
                raise UnsupportedFeatureError(
                    f"Unsupported SQL AST type: {type(sql_ast).__name__}"
                )

        except (SyntaxError, SemanticError, UnsupportedFeatureError):
            # Re-raise our custom exceptions
            raise
        except RecursionError:
            raise QueryParserError(
                f"Maximum recursion depth ({self.max_recursion_depth}) exceeded. "
                "Query may be too complex or contain circular references."
            )
        except Exception as e:
            # Catch any unexpected errors
            raise QueryParserError(
                f"Unexpected error during parsing: {str(e)}\n"
                f"Error type: {type(e).__name__}"
            )

    def _validate_with_schema(self, sql_ast: SQL_AST):
        """Validate query against schema registry"""
        if isinstance(sql_ast, SelectStatement):
            self._validate_table_exists(sql_ast.table)
            self._validate_columns_exist(sql_ast.table, sql_ast.columns)

            if sql_ast.where_clause:
                self._validate_condition_with_schema(sql_ast.table, sql_ast.where_clause)

        elif isinstance(sql_ast, SelectWithJoin):
            # Collect all tables involved
            tables = set()
            for join in sql_ast.joins:
                tables.add(join.left_table)
                tables.add(join.right_table)

            # Validate all tables exist
            for table in tables:
                self._validate_table_exists(table)

            # Validate columns with table qualification
            for column in sql_ast.columns:
                if column == "*":
                    continue

                if "." in column:
                    # Qualified column
                    table_name, col_name = column.split(".", 1)
                    if table_name not in tables:
                        raise SemanticError(
                            f"Table '{table_name}' referenced in column '{column}' "
                            f"is not in FROM/JOIN clause"
                        )
                    self._validate_column_exists(table_name, col_name)
                else:
                    # Unqualified column - check for ambiguity
                    found_tables = []
                    for table in tables:
                        if column in self.schema.get(table, {}):
                            found_tables.append(table)

                    if len(found_tables) == 0:
                        raise SemanticError(
                            f"Column '{column}' not found in any table: {', '.join(tables)}"
                        )
                    elif len(found_tables) > 1:
                        raise SemanticError(
                            f"Ambiguous column reference: '{column}' "
                            f"could be from: {', '.join(found_tables)}"
                        )

    def _validate_table_exists(self, table_name: str):
        """Validate that a table exists in schema"""
        if table_name not in self.schema:
            raise SemanticError(f"Table '{table_name}' not found in schema")

    def _validate_column_exists(self, table_name: str, column_name: str):
        """Validate that a column exists in a table"""
        if column_name not in self.schema.get(table_name, {}):
            raise SemanticError(
                f"Column '{column_name}' not found in table '{table_name}'"
            )

    def _validate_columns_exist(self, table_name: str, columns: List[str]):
        """Validate that all columns exist in the table"""
        if columns == ["*"]:
            return  # SELECT * is valid

        for column in columns:
            self._validate_column_exists(table_name, column)

    def _validate_condition_with_schema(self, table_name: str, condition: Condition):
        """Validate condition against schema types"""
        if "." in condition.column:
            # Qualified column
            col_table, col_name = condition.column.split(".", 1)
            if col_table != table_name:
                raise SemanticError(
                    f"Condition references table '{col_table}' but query is on table '{table_name}'"
                )
            column_type = self.schema.get(col_table, {}).get(col_name)
        else:
            # Unqualified column
            column_type = self.schema.get(table_name, {}).get(condition.column)

        if not column_type:
            raise SemanticError(f"Column '{condition.column}' not found in schema")

        # Type checking for value
        if condition.value is not None:
            if column_type == "INTEGER":
                if not isinstance(condition.value, (int, float)):
                    try:
                        int(condition.value)
                    except (ValueError, TypeError):
                        raise SemanticError(
                            f"Type mismatch: column '{condition.column}' is INTEGER, "
                            f"but value '{condition.value}' is not numeric"
                        )
            elif column_type == "STRING":
                if not isinstance(condition.value, str):
                    raise SemanticError(
                        f"Type mismatch: column '{condition.column}' is STRING, "
                        f"but value '{condition.value}' is not a string"
                    )

    def _parse_simple_select(self, select_stmt: SelectStatement) -> RA_Node:
        """Parse simple SELECT statement with recursion depth checking"""
        self._check_recursion_depth()

        # Start with the base relation
        ra_node = Relation(select_stmt.table)

        # Apply selection if WHERE clause exists
        if select_stmt.where_clause:
            ra_node = Selection(
                condition=self._format_condition_for_ra(select_stmt.where_clause),
                child=ra_node
            )

        # Apply projection for selected columns
        ra_node = Projection(
            columns=select_stmt.columns,
            child=ra_node
        )

        return ra_node

    def _parse_select_with_join(self, select_stmt: SelectWithJoin) -> RA_Node:
        """Parse SELECT statement with JOINs with recursion depth checking"""
        self._check_recursion_depth()

        if not select_stmt.joins:
            raise SyntaxError("SelectWithJoin must have at least one JOIN")

        # Start building the join tree from the first join
        first_join = select_stmt.joins[0]
        ra_node = Join(
            join_type=first_join.join_type,
            condition=self._format_condition_for_ra(first_join.condition) if first_join.condition else None,
            left=Relation(first_join.left_table),
            right=Relation(first_join.right_table)
        )

        # Process remaining joins
        for join_clause in select_stmt.joins[1:]:
            ra_node = Join(
                join_type=join_clause.join_type,
                condition=self._format_condition_for_ra(join_clause.condition) if join_clause.condition else None,
                left=ra_node,
                right=Relation(join_clause.right_table)
            )

        # Apply selection if WHERE clause exists
        if select_stmt.where_clause:
            ra_node = Selection(
                condition=self._format_condition_for_ra(select_stmt.where_clause),
                child=ra_node
            )

        # Apply projection
        ra_node = Projection(
            columns=select_stmt.columns,
            child=ra_node
        )

        return ra_node

    def _format_condition_for_ra(self, condition: Condition) -> str:
        """Format condition for relational algebra with NULL handling"""
        if condition.value is None:
            if condition.operator.upper() == "IS NULL":
                return f"{condition.column} IS NULL"
            elif condition.operator.upper() == "IS NOT NULL":
                return f"{condition.column} IS NOT NULL"
            else:
                # This should have been caught during validation
                return f"{condition.column} {condition.operator} NULL"
        else:
            return f"{condition.column} {condition.operator} {repr(condition.value)}"

    def _check_recursion_depth(self):
        """Check and update recursion depth"""
        self.current_recursion_depth += 1
        if self.current_recursion_depth > self.max_recursion_depth:
            raise RecursionError(
                f"Maximum recursion depth ({self.max_recursion_depth}) exceeded"
            )

    def pretty_print(self, ra_node: RA_Node, indent: int = 0) -> str:
        """Pretty print relational algebra tree with error handling"""
        try:
            return self._pretty_print_recursive(ra_node, indent)
        except Exception as e:
            return f"Error pretty printing: {str(e)}"

    def _pretty_print_recursive(self, ra_node: RA_Node, indent: int) -> str:
        """Recursive helper for pretty printing"""
        indent_str = "  " * indent

        if isinstance(ra_node, Relation):
            return f"{indent_str}Relation({ra_node.name})"

        elif isinstance(ra_node, Projection):
            columns_str = ", ".join(ra_node.columns)
            child_str = self._pretty_print_recursive(ra_node.child, indent + 1)
            return f"{indent_str}π[{columns_str}]\n{child_str}"

        elif isinstance(ra_node, Selection):
            cond_str = ra_node.condition if isinstance(ra_node.condition, str) else str(ra_node.condition)
            child_str = self._pretty_print_recursive(ra_node.child, indent + 1)
            return f"{indent_str}σ[{cond_str}]\n{child_str}"

        elif isinstance(ra_node, Join):
            join_symbol = self._get_join_symbol(ra_node.join_type)
            cond_str = f"[{ra_node.condition}]" if ra_node.condition else ""
            left_str = self._pretty_print_recursive(ra_node.left, indent + 1)
            right_str = self._pretty_print_recursive(ra_node.right, indent + 1)
            return f"{indent_str}{join_symbol}{cond_str}\n{left_str}\n{right_str}"

        return str(ra_node)

    def _get_join_symbol(self, join_type: str) -> str:
        """Get the relational algebra symbol for join type"""
        symbols = {
            "INNER": "⋈",
            "LEFT": "⟕",
            "RIGHT": "⟖",
            "FULL": "⟗"
        }
        return symbols.get(join_type, "⋈")

