    /**
     * @brief Disconnect from a target neuron
     * @throws DisconnectionError if invalid target
     */
    void disconnect_from(size_t target_id) {
        if (target_id == id_) {
            throw DisconnectionError("Cannot disconnect from self");
        }

        auto it = output_connections_.find(target_id);
        if (it == output_connections_.end()) {
            throw DisconnectionError("No connection to target neuron");
        }

        // Safely remove connection
        output_connections_.erase(it);

        try {
            // Remove reciprocal connection from target
            if (auto target = it->second.target.lock()) {
                target->remove_connection_from(id_);
            }
        } catch (const std::exception& e) {
            throw DisconnectionError("Failed to remove reciprocal connection: " + std::string(e.what()));
        }
    }

    /**
     * @brief Prune weak/inactive connections
     * @return List of disconnected neuron IDs
     */
    std::vector<size_t> prune_connections(double current_time) {
        std::vector<size_t> pruned;
        const double weight_threshold = 0.1;
        const double inactivity_timeout = 1000.0;

        for (auto it = input_connections_.begin(); it != input_connections_.end(); ) {
            if (it->second.weight < weight_threshold || 
                (current_time - it->second.last_activity_time) > inactivity_timeout) {
                pruned.push_back(it->first);
                it = input_connections_.erase(it);
            } else {
                ++it;
            }
        }
        return pruned;
    }

