     * @throws DisconnectionError if disconnection fails
     */
    void disconnect_neurons(size_t source_id, size_t target_id) {
        if (source_id == target_id) {
            throw DisconnectionError("Cannot disconnect neuron from itself");
        }

        auto source_it = neurons_.find(source_id);
        auto target_it = neurons_.find(target_id);

        if (source_it == neurons_.end() || target_it == neurons_.end()) {
            throw DisconnectionError("One or both neurons not found");
        }

        try {
            source_it->second->disconnect_from(target_id);
            target_it->second->remove_connection_from(source_id);
        } catch (const std::exception& e) {
            throw DisconnectionError("Disconnection failed: " + std::string(e.what()));
