# Note: This is actually Rust code, but placed in a Python code block as requested
# File: sysx.rs - A minimal init system for Devuan without systemd/dbus/X11 dependencies

use std::fs;
use std::io::{self, Write};
use std::process::{Command, Stdio};
use std::thread;
use std::time::Duration;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

#[derive(Debug, Clone)]
struct Service {
    name: String,
    command: String,
    args: Vec<String>,
    pid: Option<u32>,
    enabled: bool,
}

struct SysxInit {
    services: Arc<Mutex<HashMap<String, Service>>>,
    runlevel: u8,
}

impl SysxInit {
    fn new() -> Self {
        SysxInit {
            services: Arc::new(Mutex::new(HashMap::new())),
            runlevel: 3, // Default multi-user runlevel
        }
    }

    // Load services from configuration directory
    fn load_services(&self) -> io::Result<()> {
        // Load services from /etc/sysx/services/
        let services_dir = "/etc/sysx/services/";

        if let Ok(entries) = fs::read_dir(services_dir) {
            for entry in entries.flatten() {
                if let Ok(content) = fs::read_to_string(entry.path()) {
                    self.parse_service_file(&content)?;
                }
            }
        }
        Ok(())
    }

    // Parse individual service configuration files
    fn parse_service_file(&self, content: &str) -> io::Result<()> {
        let mut name = String::new();
        let mut command = String::new();
        let mut args = Vec::new();
        let mut enabled = false;

        for line in content.lines() {
            let parts: Vec<&str> = line.splitn(2, '=').collect();
            if parts.len() == 2 {
                match parts[0].trim() {
                    "NAME" => name = parts[1].trim().to_string(),
                    "COMMAND" => command = parts[1].trim().to_string(),
                    "ARGS" => args = parts[1].split_whitespace().map(String::from).collect(),
                    "ENABLED" => enabled = parts[1].trim() == "true",
                    _ => {}
                }
            }
        }

        if !name.is_empty() && !command.is_empty() {
            let service = Service {
                name: name.clone(),
                command,
                args,
                pid: None,
                enabled,
            };

            let mut services = self.services.lock().unwrap();
            services.insert(name, service);
        }

        Ok(())
    }

    // Start a service by executing its command
    fn start_service(&self, service_name: &str) -> io::Result<()> {
        let mut services = self.services.lock().unwrap();

        if let Some(service) = services.get_mut(service_name) {
            println!("Starting service: {}", service_name);

            let mut cmd = Command::new(&service.command);
            cmd.args(&service.args);
            cmd.stdout(Stdio::null());
            cmd.stderr(Stdio::null());

            match cmd.spawn() {
                Ok(child) => {
                    service.pid = Some(child.id());
                    println!("Service {} started with PID: {}", service_name, child.id());
                    Ok(())
                }
                Err(e) => {
                    eprintln!("Failed to start service {}: {}", service_name, e);
                    Err(e)
                }
            }
        } else {
            eprintln!("Service {} not found", service_name);
            Err(io::Error::new(io::ErrorKind::NotFound, "Service not found"))
        }
    }

    // Stop a service by sending SIGTERM to its PID
    fn stop_service(&self, service_name: &str) -> io::Result<()> {
        let mut services = self.services.lock().unwrap();

        if let Some(service) = services.get_mut(service_name) {
            if let Some(pid) = service.pid {
                println!("Stopping service: {} (PID: {})", service_name, pid);

                // Send SIGTERM for graceful shutdown
                let _ = Command::new("kill")
                    .arg("-TERM")
                    .arg(pid.to_string())
                    .output();

                service.pid = None;
            }
        }
        Ok(())
    }

    // List all services with their status
    fn list_services(&self) {
        let services = self.services.lock().unwrap();

        println!("{:<20} {:<10} {:<10} {:<10}", "Service", "Status", "PID", "Enabled");
        println!("{}", "-".repeat(60));

        for (name, service) in services.iter() {
            let status = if service.pid.is_some() { "Running" } else { "Stopped" };
            let pid = service.pid.map_or("N/A".to_string(), |p| p.to_string());
            let enabled = if service.enabled { "Yes" } else { "No" };

            println!("{:<20} {:<10} {:<10} {:<10}", name, status, pid, enabled);
        }
    }

    // Change system runlevel and perform associated actions
    fn change_runlevel(&mut self, new_level: u8) {
        println!("Changing runlevel from {} to {}", self.runlevel, new_level);
        self.runlevel = new_level;

        // Execute actions based on the new runlevel
        match new_level {
            0 => self.shutdown(),
            1 => self.single_user_mode(),
            3 => self.multi_user_mode(),
            6 => self.reboot(),
            _ => println!("Runlevel {} not specifically handled", new_level),
        }
    }

    // Handle system shutdown (runlevel 0)
    fn shutdown(&self) {
        println!("System shutdown initiated");

        // Stop all running services gracefully
        let services = self.services.lock().unwrap();
        for (name, _) in services.iter() {
            let _ = self.stop_service(name);
        }

        // Sync filesystems to ensure data integrity
        let _ = Command::new("sync").output();

        // Execute poweroff command
        let _ = Command::new("poweroff").output();
    }

    // Handle system reboot (runlevel 6)
    fn reboot(&self) {
        println!("System reboot initiated");

        // Stop all running services
        let services = self.services.lock().unwrap();
        for (name, _) in services.iter() {
            let _ = self.stop_service(name);
        }

        // Sync filesystems
        let _ = Command::new("sync").output();

        // Execute reboot command
        let _ = Command::new("reboot").output();
    }

    // Enter single-user mode (runlevel 1)
    fn single_user_mode(&self) {
        println!("Entering single-user mode");

        // Stop non-essential services, keep essential ones running
        let services = self.services.lock().unwrap();
        for (name, service) in services.iter() {
            // In a real implementation, you'd have a way to mark services as essential
            if !name.contains("essential") && service.pid.is_some() {
                let _ = self.stop_service(name);
            }
        }
    }

    // Enter multi-user mode (runlevel 3)
    fn multi_user_mode(&self) {
        println!("Entering multi-user mode");

        // Start all enabled services that aren't already running
        let services = self.services.lock().unwrap();
        for (name, service) in services.iter() {
            if service.enabled && service.pid.is_none() {
                let _ = self.start_service(name);
            }
        }
    }

    // Initialize essential system tasks
    fn initialize_system(&self) -> io::Result<()> {
        println!("Initializing essential system tasks...");

        // 1. Mount filesystems from /etc/fstab
        println!("Mounting filesystems...");
        let _ = Command::new("mount")
            .arg("-a")  // Mount all filesystems from /etc/fstab
            .output();

        // 2. Start network interfaces
        println!("Starting network interfaces...");
        let _ = Command::new("ifup")
            .arg("-a")  // Bring up all interfaces from /etc/network/interfaces
            .output();

        // 3. Set hostname
        println!("Setting hostname...");
        if let Ok(hostname) = fs::read_to_string("/etc/hostname") {
            let _ = Command::new("hostname")
                .arg(hostname.trim())
                .output();
        }

        // 4. Set up loopback interface
        println!("Setting up loopback interface...");
        let _ = Command::new("ifup")
            .arg("lo")
            .output();

        // 5. Load kernel modules if needed
        println!("Loading kernel modules...");
        let _ = Command::new("modprobe")
            .arg("-a")
            .output();

        Ok(())
    }

    // Main initialization routine
    fn run(&mut self) -> io::Result<()> {
        println!("Sysx Init System starting...");

        // Step 1: Initialize essential system tasks
        self.initialize_system()?;

        // Step 2: Load service configurations
        self.load_services()?;

        // Step 3: Start enabled services based on current runlevel
        self.multi_user_mode();

        // Step 4: Enter command loop for interactive management
        self.command_loop()
    }

    // Interactive command-line interface
    fn command_loop(&self) -> io::Result<()> {
        println!("Sysx ready. Type 'help' for commands.");

        loop {
            print!("sysx> ");
            io::stdout().flush()?;

            let mut input = String::new();
            io::stdin().read_line(&mut input)?;

            let parts: Vec<&str> = input.trim().split_whitespace().collect();
            if parts.is_empty() {
                continue;
            }

            match parts[0] {
                "start" => {
                    if parts.len() > 1 {
                        let _ = self.start_service(parts[1]);
                    } else {
                        println!("Usage: start <service>");
                    }
                }
                "stop" => {
                    if parts.len() > 1 {
                        let _ = self.stop_service(parts[1]);
                    } else {
                        println!("Usage: stop <service>");
                    }
                }
                "list" => self.list_services(),
                "runlevel" => {
                    if parts.len() > 1 {
                        if let Ok(level) = parts[1].parse::<u8>() {
                            // Note: In real implementation, this would need mutable access
                            println!("Would change to runlevel {}", level);
                        }
                    } else {
                        println!("Current runlevel: {}", self.runlevel);
                    }
                }
                "shutdown" => {
                    println!("Initiating shutdown...");
                    break;
                }
                "reboot" => {
                    println!("Initiating reboot...");
                    break;
                }
                "mount" => {
                    println!("Mounting filesystems...");
                    let _ = Command::new("mount").arg("-a").output();
                }
                "network" => {
                    println!("Starting network...");
                    let _ = Command::new("ifup").arg("-a").output();
                }
                "help" => {
                    println!("Available commands:");
                    println!("  start <service>    - Start a service");
                    println!("  stop <service>     - Stop a service");
                    println!("  list               - List all services");
                    println!("  runlevel [n]       - Show or change runlevel");
                    println!("  shutdown           - Shutdown the system");
                    println!("  reboot             - Reboot the system");
                    println!("  mount              - Mount all filesystems");
                    println!("  network            - Start network interfaces");
                    println!("  help               - Show this help");
                    println!("  exit               - Exit the command interface");
                }
                "exit" => break,
                _ => println!("Unknown command. Type 'help' for available commands."),
            }
        }

        Ok(())
    }
}

fn main() -> io::Result<()> {
    let mut sysx = SysxInit::new();
    sysx.run()
}

